<?php get_header(); ?><header class="page-hero"><div class="narrow"><div class="eyebrow">Journal</div><h1>Notes from the stack.</h1></div></header><main id="content" class="article"><div class="narrow"><div class="blog-grid" style="background:var(--line)"><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="post-card" style="background:var(--paper);color:var(--ink)"><div class="post-date" style="color:var(--bronze)"><?php echo esc_html(get_the_date('M d, Y')); ?></div><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p style="color:rgba(16,17,15,.62)"><?php echo esc_html(kk_excerpt(get_the_excerpt(),24)); ?></p></article><?php endwhile; else: ?><p>No published notes yet.</p><?php endif; ?></div><?php the_posts_pagination(); ?></div></main><?php get_footer(); ?>
